PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS pais (codigo_pais TEXT PRIMARY KEY, nombre_oficial TEXT NOT NULL, organismo_polar TEXT NOT NULL, presupuesto_anual NUMERIC NOT NULL CHECK(presupuesto_anual>=0));
CREATE TABLE IF NOT EXISTS base_cientifica (codigo_base TEXT PRIMARY KEY, codigo_pais TEXT NOT NULL REFERENCES pais(codigo_pais) ON UPDATE CASCADE ON DELETE RESTRICT, nombre TEXT NOT NULL, latitud REAL NOT NULL CHECK(latitud BETWEEN -90 AND 90), longitud REAL NOT NULL CHECK(longitud BETWEEN -180 AND 180), fecha_instalacion TEXT NOT NULL, capacidad_max INTEGER NOT NULL CHECK(capacidad_max>0), presupuesto NUMERIC NOT NULL CHECK(presupuesto>=0), nivel_aislamiento TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sector_investigacion (codigo_base TEXT NOT NULL, nro_interno INTEGER NOT NULL CHECK(nro_interno>0), nombre TEXT NOT NULL, superficie_km2 REAL NOT NULL CHECK(superficie_km2>=0), condiciones_clima TEXT NOT NULL, nivel_acceso TEXT NOT NULL, PRIMARY KEY(codigo_base,nro_interno), FOREIGN KEY(codigo_base) REFERENCES base_cientifica(codigo_base) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS personal (id_personal TEXT PRIMARY KEY, nombre TEXT NOT NULL, apellido TEXT NOT NULL, email TEXT UNIQUE, fecha_ingreso TEXT NOT NULL, tipo_funcion TEXT NOT NULL, id_supervisor TEXT REFERENCES personal(id_personal) ON DELETE SET NULL ON UPDATE CASCADE, CHECK(id_supervisor IS NULL OR id_supervisor<>id_personal));
CREATE TABLE IF NOT EXISTS telefono_personal (id_personal TEXT NOT NULL REFERENCES personal(id_personal) ON DELETE CASCADE ON UPDATE CASCADE, telefono TEXT NOT NULL, PRIMARY KEY(id_personal, telefono));
CREATE TABLE IF NOT EXISTS expedicion (codigo_expedicion TEXT PRIMARY KEY, codigo_base TEXT NOT NULL REFERENCES base_cientifica(codigo_base) ON DELETE RESTRICT ON UPDATE CASCADE, id_responsable TEXT NOT NULL REFERENCES personal(id_personal) ON DELETE RESTRICT ON UPDATE CASCADE, fecha_inicio TEXT NOT NULL, duracion_dias INTEGER NOT NULL CHECK(duracion_dias>0), capacidad_max INTEGER NOT NULL CHECK(capacidad_max>0));
CREATE TABLE IF NOT EXISTS participacion (codigo_expedicion TEXT NOT NULL, id_personal TEXT NOT NULL REFERENCES personal(id_personal) ON DELETE RESTRICT, funcion TEXT NOT NULL, fecha_incorporacion TEXT NOT NULL, estado TEXT NOT NULL CHECK(estado IN ('Activa','Finalizada','Suspendida')), observaciones TEXT, PRIMARY KEY(codigo_expedicion,id_personal), FOREIGN KEY(codigo_expedicion) REFERENCES expedicion(codigo_expedicion) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS muestra (codigo_muestra TEXT PRIMARY KEY, descripcion TEXT NOT NULL, fecha_hallazgo TEXT NOT NULL, estado_conservacion TEXT NOT NULL, tipo_especializacion TEXT CHECK(tipo_especializacion IN ('BIO','GEO','CLI') OR tipo_especializacion IS NULL));
CREATE TABLE IF NOT EXISTS muestra_biologica (codigo_muestra TEXT PRIMARY KEY REFERENCES muestra(codigo_muestra) ON DELETE CASCADE, especie TEXT NOT NULL, reino TEXT NOT NULL, adn_extraido TEXT NOT NULL CHECK(adn_extraido IN ('S','N')));
CREATE TABLE IF NOT EXISTS muestra_geologica (codigo_muestra TEXT PRIMARY KEY REFERENCES muestra(codigo_muestra) ON DELETE CASCADE, tipo_roca TEXT NOT NULL, era_geologica TEXT NOT NULL, dureza_mohs REAL NOT NULL CHECK(dureza_mohs BETWEEN 1 AND 10));
CREATE TABLE IF NOT EXISTS muestra_climatica (codigo_muestra TEXT PRIMARY KEY REFERENCES muestra(codigo_muestra) ON DELETE CASCADE, variable_clima TEXT NOT NULL, valor_medido REAL NOT NULL, unidad_medida TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recoleccion (codigo_expedicion TEXT NOT NULL, nro_correlativo INTEGER NOT NULL CHECK(nro_correlativo>0), codigo_muestra TEXT NOT NULL UNIQUE REFERENCES muestra(codigo_muestra) ON DELETE RESTRICT, codigo_base TEXT NOT NULL, nro_interno INTEGER NOT NULL, id_responsable TEXT NOT NULL REFERENCES personal(id_personal) ON DELETE RESTRICT, fecha TEXT NOT NULL, PRIMARY KEY(codigo_expedicion,nro_correlativo), FOREIGN KEY(codigo_expedicion) REFERENCES expedicion(codigo_expedicion) ON DELETE CASCADE, FOREIGN KEY(codigo_base,nro_interno) REFERENCES sector_investigacion(codigo_base,nro_interno) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS evaluacion (codigo_expedicion TEXT NOT NULL, nro_correlativo INTEGER NOT NULL CHECK(nro_correlativo>0), id_personal TEXT NOT NULL, fecha TEXT NOT NULL, calificacion REAL NOT NULL CHECK(calificacion BETWEEN 1 AND 5), comentario TEXT, PRIMARY KEY(codigo_expedicion,nro_correlativo), FOREIGN KEY(codigo_expedicion,id_personal) REFERENCES participacion(codigo_expedicion,id_personal) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cuenta_usuario (id_cuenta TEXT PRIMARY KEY, id_personal TEXT NOT NULL UNIQUE REFERENCES personal(id_personal) ON DELETE CASCADE, nombre_usuario TEXT NOT NULL UNIQUE, hash_clave TEXT NOT NULL, estado TEXT NOT NULL CHECK(estado IN ('Activa','Inactiva')), ultimo_acceso TEXT);
CREATE TABLE IF NOT EXISTS rol (id_rol TEXT PRIMARY KEY, nombre_rol TEXT NOT NULL UNIQUE, descripcion TEXT NOT NULL, permisos TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS asignacion_rol (id_cuenta TEXT NOT NULL REFERENCES cuenta_usuario(id_cuenta) ON DELETE CASCADE, id_rol TEXT NOT NULL REFERENCES rol(id_rol) ON DELETE RESTRICT, fecha_asignacion TEXT NOT NULL, PRIMARY KEY(id_cuenta,id_rol));
-- Triggers aseguran que el subtipo coincida con el discriminador y sea disjunto.
CREATE TRIGGER IF NOT EXISTS trg_bio BEFORE INSERT ON muestra_biologica BEGIN SELECT RAISE(ABORT,'Muestra no es BIO') WHERE (SELECT tipo_especializacion FROM muestra WHERE codigo_muestra=NEW.codigo_muestra) IS NOT 'BIO'; SELECT RAISE(ABORT,'Subtipo duplicado') WHERE EXISTS(SELECT 1 FROM muestra_geologica WHERE codigo_muestra=NEW.codigo_muestra) OR EXISTS(SELECT 1 FROM muestra_climatica WHERE codigo_muestra=NEW.codigo_muestra); END;
CREATE TRIGGER IF NOT EXISTS trg_geo BEFORE INSERT ON muestra_geologica BEGIN SELECT RAISE(ABORT,'Muestra no es GEO') WHERE (SELECT tipo_especializacion FROM muestra WHERE codigo_muestra=NEW.codigo_muestra) IS NOT 'GEO'; SELECT RAISE(ABORT,'Subtipo duplicado') WHERE EXISTS(SELECT 1 FROM muestra_biologica WHERE codigo_muestra=NEW.codigo_muestra) OR EXISTS(SELECT 1 FROM muestra_climatica WHERE codigo_muestra=NEW.codigo_muestra); END;
CREATE TRIGGER IF NOT EXISTS trg_cli BEFORE INSERT ON muestra_climatica BEGIN SELECT RAISE(ABORT,'Muestra no es CLI') WHERE (SELECT tipo_especializacion FROM muestra WHERE codigo_muestra=NEW.codigo_muestra) IS NOT 'CLI'; SELECT RAISE(ABORT,'Subtipo duplicado') WHERE EXISTS(SELECT 1 FROM muestra_biologica WHERE codigo_muestra=NEW.codigo_muestra) OR EXISTS(SELECT 1 FROM muestra_geologica WHERE codigo_muestra=NEW.codigo_muestra); END;
CREATE TRIGGER IF NOT EXISTS trg_tipo_update BEFORE UPDATE OF tipo_especializacion ON muestra BEGIN SELECT RAISE(ABORT,'Elimine primero el subtipo previo') WHERE (EXISTS(SELECT 1 FROM muestra_biologica WHERE codigo_muestra=NEW.codigo_muestra) AND NEW.tipo_especializacion IS NOT 'BIO') OR (EXISTS(SELECT 1 FROM muestra_geologica WHERE codigo_muestra=NEW.codigo_muestra) AND NEW.tipo_especializacion IS NOT 'GEO') OR (EXISTS(SELECT 1 FROM muestra_climatica WHERE codigo_muestra=NEW.codigo_muestra) AND NEW.tipo_especializacion IS NOT 'CLI'); END;
-- Verificar que el sector pertenece a la misma base donde se desarrolla la expedicion.
CREATE TRIGGER IF NOT EXISTS trg_recoleccion_base BEFORE INSERT ON recoleccion BEGIN SELECT RAISE(ABORT,'Sector de base diferente de la expedicion') WHERE NEW.codigo_base <> (SELECT codigo_base FROM expedicion WHERE codigo_expedicion=NEW.codigo_expedicion); END;
